insert into public.team_name_master (source,source_name,source_key,team_key,hkjc_name_en,hkjc_name_zh,status,confidence,event_count,first_seen_at,last_seen_at,evidence_sources,updated_at) values ('FOREBET','A. Italiano','aitaliano','HKJC:audaxitaliano','Audax Italiano','奧達斯','VERIFIED',1.00,1,now(),now(),'["HKJC_EVENT_PAIR_FB5609","FOREBET_MODEL","LEAGUE_CHC"]'::jsonb,now()) on conflict (source,source_key,team_key) do update set status='VERIFIED',confidence=greatest(team_name_master.confidence,excluded.confidence),last_seen_at=now(),updated_at=now(); insert into public.competition_name_master (source,source_competition,source_key,canonical_tournament,status,confidence,event_count,first_seen_at,last_seen_at,evidence_sources,updated_at) values ('FOREBET','Chile: Copa Chile - Play Offs','chilecopachileplayoffs','CHC','VERIFIED',1.00,1,now(),now(),'["HKJC_EVENT_PAIR_FB5609","FOREBET_MODEL"]'::jsonb,now()) on conflict (source,source_key,canonical_tournament) do update set status='VERIFIED',confidence=greatest(competition_name_master.confidence,excluded.confidence),last_seen_at=now(),updated_at=now();
